import django.db.models.deletion
from django.conf import settings
from django.db import migrations, models
from django.utils import timezone


def crear_periodos_para_inscripciones_existentes(apps, schema_editor):
    Periodo = apps.get_model('capacitacion', 'Periodo')
    Inscripcion = apps.get_model('capacitacion', 'Inscripcion')

    cursos_sin_periodo = (
        Inscripcion.objects.filter(periodo__isnull=True)
        .values_list('curso_id', flat=True)
        .distinct()
    )
    for curso_id in cursos_sin_periodo:
        primera = (
            Inscripcion.objects.filter(curso_id=curso_id, periodo__isnull=True)
            .order_by('inscrito_at')
            .first()
        )
        fecha_inicio = primera.inscrito_at.date() if primera else timezone.now().date()
        periodo = Periodo.objects.create(
            curso_id=curso_id,
            nombre='Periodo histórico (migración automática)',
            fecha_inicio=fecha_inicio,
            estado='cerrado',
        )
        Inscripcion.objects.filter(curso_id=curso_id, periodo__isnull=True).update(periodo=periodo)


